// Package greeter is a small example showing how to structure code so that
// its dependencies can be mocked in tests.
package greeter

import (
	"errors"
	"fmt"
)

// NameStore looks up a user's display name by ID.
type NameStore interface {
	Name(id int) (string, error)
}

// ErrInvalidID is returned when a non-positive ID is requested.
var ErrInvalidID = errors.New("greeter: invalid id")

// Greeter builds greetings using a NameStore.
type Greeter struct {
	store NameStore
}

// New returns a Greeter backed by store.
func New(store NameStore) *Greeter {
	return &Greeter{store: store}
}

// Greet returns a greeting for the user with the given ID.
func (g *Greeter) Greet(id int) (string, error) {
	if id <= 0 {
		return "", ErrInvalidID
	}
	name, err := g.store.Name(id)
	if err != nil {
		return "", fmt.Errorf("greeter: lookup %d: %w", id, err)
	}
	return "Hello, " + name + "!", nil
}
EOF
cat > greeter/greeter_test.go <<'EOF'
package greeter

import (
	"errors"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/mock"
	"github.com/stretchr/testify/require"
)

// mockNameStore is a testify mock implementing NameStore.
type mockNameStore struct {
	mock.Mock
}

func (m *mockNameStore) Name(id int) (string, error) {
	args := m.Called(id)
	return args.String(0), args.Error(1)
}

func TestGreet(t *testing.T) {
	store := new(mockNameStore)
	store.On("Name", 42).Return("Gopher", nil).Once()

	got, err := New(store).Greet(42)

	require.NoError(t, err)
	assert.Equal(t, "Hello, Gopher!", got)
	store.AssertExpectations(t)
}

func TestGreetStoreError(t *testing.T) {
	errNotFound := errors.New("not found")
	store := new(mockNameStore)
	store.On("Name", 7).Return("", errNotFound).Once()

	_, err := New(store).Greet(7)

	require.Error(t, err)
	assert.ErrorIs(t, err, errNotFound)
	store.AssertExpectations(t)
}

func TestGreetInvalidID(t *testing.T) {
	store := new(mockNameStore)

	_, err := New(store).Greet(0)

	assert.ErrorIs(t, err, ErrInvalidID)
	store.AssertNotCalled(t, "Name", mock.Anything)
}
EOF
